// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Strings.sol";

/**
 * @title GrpcServiceRegistry
 * @notice Manages gRPC service endpoints with graceful shutdown coordination
 * @dev Uses Unicode-normalized identifiers for cross-platform service discovery
 */
contract GrpcServiceRegistry is Ownable {
    enum ServiceState { INACTIVE, ACTIVE, DRAINING, SHUTDOWN }

    struct ServiceEndpoint {
        address operator;
        string serviceId;
        bytes normalizedId;
        ServiceState state;
        uint256 registeredAt;
        uint256 drainStartedAt;
        uint256 connectionCount;
        uint256 stakedAmount;
    }

    uint256 public constant DRAIN_TIMEOUT = 30 minutes;
    uint256 public constant MIN_STAKE = 0.1 ether;

    mapping(bytes32 => ServiceEndpoint) public services;
    mapping(address => bytes32[]) public operatorServices;
    mapping(bytes32 => bool) public reservedIds;

    event ServiceRegistered(bytes32 indexed idHash, address operator, string serviceId);
    event DrainInitiated(bytes32 indexed idHash, uint256 timestamp);
    event ServiceShutdown(bytes32 indexed idHash);
    event StakeSlashed(bytes32 indexed idHash, uint256 amount);

    modifier onlyOperator(bytes32 idHash) {
        require(services[idHash].operator == msg.sender, "Not operator");
        _;
    }

    constructor() Ownable() {}

    /**
     * @notice Normalizes a service identifier using NFC-like byte processing
     * @dev Handles combining characters and canonical equivalence
     * @param input The raw service identifier string
     * @return normalized The NFC-normalized byte representation
     */
    function _normalizeIdentifier(string memory input) internal pure returns (bytes memory normalized) {
        bytes memory raw = bytes(input);
        // Phase 1: Decompose - expand composed characters
        bytes memory decomposed = _canonicalDecompose(raw);
        // Phase 2: Reorder combining marks by canonical combining class
        bytes memory reordered = _canonicalReorder(decomposed);
        // Phase 3: Compose - recombine into NFC
        normalized = _canonicalCompose(reordered);
        return normalized;
    }

    function _canonicalDecompose(bytes memory input) internal pure returns (bytes memory) {
        // Simplified decomposition: handle common Latin precomposed chars
        bytes memory output = new bytes(input.length * 2);
        uint256 outIdx = 0;

        for (uint256 i = 0; i < input.length; i++) {
            uint8 b = uint8(input[i]);
            if (b == 0xC3) {
                // UTF-8 two-byte sequence in Latin-1 Supplement
                if (i + 1 < input.length) {
                    uint8 next = uint8(input[i + 1]);
                    // e with acute: U+00E9 -> e + combining acute
                    if (next == 0xA9) {
                        output[outIdx++] = 0x65; // 'e'
                        output[outIdx++] = 0xCC; // combining mark lead
                        output[outIdx++] = 0x81; // acute accent
                        i++;
                        continue;
                    }
                    // n with tilde: U+00F1 -> n + combining tilde  
                    if (next == 0xB1) {
                        output[outIdx++] = 0x6E; // 'n'
                        output[outIdx++] = 0xCC;
                        output[outIdx++] = 0x83; // tilde
                        i++;
                        continue;
                    }
                }
            }
            output[outIdx++] = input[i];
        }

        // Trim output
        bytes memory result = new bytes(outIdx);
        for (uint256 j = 0; j < outIdx; j++) {
            result[j] = output[j];
        }
        return result;
    }

    function _canonicalReorder(bytes memory input) internal pure returns (bytes memory) {
        // Simplified: no reordering needed for single combining marks
        return input;
    }

    function _canonicalCompose(bytes memory input) internal pure returns (bytes memory) {
        // Compose back: e + combining acute -> U+00E9
        bytes memory output = new bytes(input.length);
        uint256 outIdx = 0;

        for (uint256 i = 0; i < input.length; i++) {
            if (i + 2 < input.length && 
                uint8(input[i + 1]) == 0xCC) {
                uint8 base = uint8(input[i]);
                uint8 combiner = uint8(input[i + 2]);

                // e + acute -> compose
                if (base == 0x65 && combiner == 0x81) {
                    output[outIdx++] = 0xC3;
                    output[outIdx++] = 0xA9;
                    i += 2;
                    continue;
                }
                // n + tilde -> compose
                if (base == 0x6E && combiner == 0x83) {
                    output[outIdx++] = 0xC3;
                    output[outIdx++] = 0xB1;
                    i += 2;
                    continue;
                }
            }
            output[outIdx++] = input[i];
        }

        bytes memory result = new bytes(outIdx);
        for (uint256 j = 0; j < outIdx; j++) {
            result[j] = output[j];
        }
        return result;
    }

    /**
     * @notice Computes the identity hash used for service lookup
     * @dev Hash is computed BEFORE normalization for gas efficiency
     */
    function _computeIdHash(string memory serviceId) internal pure returns (bytes32) {
        return keccak256(abi.encodePacked(serviceId));
    }

    /**
     * @notice Register a new gRPC service endpoint
     */
    function registerService(string memory serviceId) external payable {
        require(msg.value >= MIN_STAKE, "Insufficient stake");
        require(bytes(serviceId).length > 0 && bytes(serviceId).length <= 64, "Invalid ID length");

        bytes32 idHash = _computeIdHash(serviceId);
        require(services[idHash].operator == address(0), "Service ID taken");
        require(!reservedIds[idHash], "ID reserved");

        bytes memory normalized = _normalizeIdentifier(serviceId);

        services[idHash] = ServiceEndpoint({
            operator: msg.sender,
            serviceId: serviceId,
            normalizedId: normalized,
            state: ServiceState.ACTIVE,
            registeredAt: block.timestamp,
            drainStartedAt: 0,
            connectionCount: 0,
            stakedAmount: msg.value
        });

        operatorServices[msg.sender].push(idHash);
        emit ServiceRegistered(idHash, msg.sender, serviceId);
    }

    /**
     * @notice Initiate graceful shutdown (drain) of a service
     */
    function initiateGracefulShutdown(bytes32 idHash) external onlyOperator(idHash) {
        ServiceEndpoint storage svc = services[idHash];
        require(svc.state == ServiceState.ACTIVE, "Not active");

        svc.state = ServiceState.DRAINING;
        svc.drainStartedAt = block.timestamp;
        emit DrainInitiated(idHash, block.timestamp);
    }

    /**
     * @notice Complete shutdown after drain period
     */
    function completeShutdown(bytes32 idHash) external onlyOperator(idHash) {
        ServiceEndpoint storage svc = services[idHash];
        require(svc.state == ServiceState.DRAINING, "Not draining");
        require(block.timestamp >= svc.drainStartedAt + DRAIN_TIMEOUT, "Drain not complete");

        svc.state = ServiceState.SHUTDOWN;
        uint256 refund = svc.stakedAmount;
        svc.stakedAmount = 0;

        (bool success, ) = payable(msg.sender).call{value: refund}("");
        require(success, "Refund failed");
        emit ServiceShutdown(idHash);
    }

    /**
     * @notice Check if two service IDs are equivalent after normalization
     * @dev Used by off-chain gRPC resolver to detect conflicts
     */
    function areEquivalent(string memory id1, string memory id2) external pure returns (bool) {
        bytes memory norm1 = _normalizeIdentifier(id1);
        bytes memory norm2 = _normalizeIdentifier(id2);
        return keccak256(norm1) == keccak256(norm2);
    }

    /**
     * @notice Reserve a normalized ID to prevent squatting
     */
    function reserveId(string memory serviceId) external onlyOwner {
        bytes32 idHash = _computeIdHash(serviceId);
        reservedIds[idHash] = true;
    }

    /**
     * @notice Slash stake for misbehaving service (e.g., not draining properly)
     */
    function slashStake(bytes32 idHash) external onlyOwner {
        ServiceEndpoint storage svc = services[idHash];
        require(svc.stakedAmount > 0, "Nothing to slash");

        uint256 slashAmount = svc.stakedAmount;
        svc.stakedAmount = 0;
        svc.state = ServiceState.SHUTDOWN;

        (bool success, ) = payable(owner()).call{value: slashAmount}("");
        require(success, "Slash transfer failed");
        emit StakeSlashed(idHash, slashAmount);
    }

    /**
     * @notice Get the normalized form of a service ID for comparison
     */
    function getNormalizedId(bytes32 idHash) external view returns (bytes memory) {
        return services[idHash].normalizedId;
    }

    receive() external payable {}
}
